local playerGui = player:WaitForChild("PlayerGui")

-- Destroying a previous copy also runs its cleanup before this copy starts.
for _, guiName in ipairs({"PumpkinCollector", "ImmortalityIncremental"}) do
    local previous = playerGui:FindFirstChild(guiName)
    if previous then previous:Destroy() end
end

