local function fitPanel()
    local camera = workspace.CurrentCamera
    if camera then
        local viewport = camera.ViewportSize
        panelScale.Scale = math.max(0.1, math.min(1, (viewport.X - 32) / 360, (viewport.Y - 76) / 628))
        if introScale then
            introScale.Scale = math.max(0.1, math.min(1, (viewport.X - 32) / 520, (viewport.Y - 76) / 240))
        end
    end
end
local function watchCamera()
    if cameraSizeConnection then cameraSizeConnection:Disconnect() end
    local camera = workspace.CurrentCamera
    if camera then cameraSizeConnection = connect(camera:GetPropertyChangedSignal("ViewportSize"), fitPanel) end
    fitPanel()
end
connect(workspace:GetPropertyChangedSignal("CurrentCamera"), watchCamera)
