local yieldLoading, yieldLoaded = false, false
local yieldHovered, yieldPressed = false, nil
local yieldTweens = {}
local function refreshYieldAppearance()
    for _, tween in ipairs(yieldTweens) do tween:Cancel() end
    table.clear(yieldTweens)
    local interactive = not yieldLoading and not yieldLoaded
    local scale = 1
    if interactive then
        if yieldPressed then scale = 0.98 elseif yieldHovered then scale = 1.015 end
    end
    local properties = {
        {yieldScale, {Scale = scale}},
        {yieldBorder, {Transparency = interactive and yieldHovered and 0.1 or 0.45}},
        {yieldButton, {BackgroundColor3 = yieldLoading and Color3.fromRGB(185, 185, 200)
            or (interactive and yieldHovered and Color3.new(1, 1, 1) or Color3.fromRGB(230, 230, 245))}},
    }
    for _, entry in ipairs(properties) do
        local tween = TweenService:Create(entry[1], TweenInfo.new(0.14, Enum.EasingStyle.Quad), entry[2])
        table.insert(yieldTweens, tween)
        tween:Play()
    end
end
connect(yieldButton.MouseEnter, function() yieldHovered = true; refreshYieldAppearance() end)
connect(yieldButton.MouseLeave, function() yieldHovered = false; refreshYieldAppearance() end)
connect(yieldButton.InputBegan, function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        yieldPressed = input
        refreshYieldAppearance()
    end
end)
connect(UIS.InputEnded, function(input)
    if input == yieldPressed then
        yieldPressed = nil
        refreshYieldAppearance()
    end
end)
