connect(yieldButton.Activated, function()
    if yieldLoading or yieldLoaded then return end
    yieldLoading = true
    yieldCaption.Text = "Loading..."
    yieldArrow.Text = "…"
    refreshYieldAppearance()
    task.spawn(function()
        local ok, err = pcall(function()
            local source = game:HttpGet("https://raw.githubusercontent.com/EdgeIY/infiniteyield/master/source")
            local chunk, compileError = loadstring(source)
            if not chunk then error(compileError) end
            chunk()
        end)
        yieldLoading = false
        yieldLoaded = ok
        if not alive then return end
        yieldCaption.Text = ok and "Infinite Yield Loaded" or "Retry Infinite Yield"
        yieldArrow.Text = ok and "✓" or "›"
        refreshYieldAppearance()
        if ok then
            notify("Infinite Yield loaded.")
        else
            notify("Infinite Yield failed; see console for details.")
            warn("[ImmortalityIncremental] Infinite Yield: " .. tostring(err))
        end
    end)
end)

local function teleport(name, position)
    local character = player.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid or humanoid.Health <= 0 then
        notify("Character unavailable; try the teleport again after spawning.")
        return
    end
    setCollector(nil)
    humanoid:MoveTo(root.Position)
    root.AssemblyLinearVelocity = Vector3.zero
    root.AssemblyAngularVelocity = Vector3.zero
    root.CFrame = CFrame.new(position)
    notify("Teleported to " .. name .. ". Collectors are OFF.")
end

