-- END EMBEDDED TEXTURES

local function decodeBase64(encoded)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local values = {}
    for index = 1, #alphabet do
        values[alphabet:sub(index, index)] = index - 1
    end
    encoded = encoded:gsub("%s", "")
    local decoded = {}
    for index = 1, #encoded, 4 do
        local a = values[encoded:sub(index, index)]
        local b = values[encoded:sub(index + 1, index + 1)]
        local c = values[encoded:sub(index + 2, index + 2)]
        local d = values[encoded:sub(index + 3, index + 3)]
        local packed = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
        local bytes = string.char(math.floor(packed / 65536) % 256)
        if c then bytes = bytes .. string.char(math.floor(packed / 256) % 256) end
        if d then bytes = bytes .. string.char(packed % 256) end
        decoded[#decoded + 1] = bytes
    end
    return table.concat(decoded)
end

local textureSupportWarning = false
local function textureAsset(name)
    if textureAssetIds[name] then return textureAssetIds[name] end
    if not textureData[name] then return nil end
    local registerAsset = getcustomasset or getsynasset
    if type(writefile) ~= "function" or type(registerAsset) ~= "function" then
        if not textureSupportWarning then
            textureSupportWarning = true
            warn("[ImmortalityIncremental] Textures need writefile and getcustomasset/getsynasset, or uploaded textureAssetIds. Using button colors.")
        end
        return nil
    end
    local ok, asset = pcall(function()
        local filename = "PumpkinCollector_" .. name .. "_texture_v1.png"
        writefile(filename, decodeBase64(textureData[name]))
        return registerAsset(filename)
    end)
    if ok and type(asset) == "string" and asset ~= "" then return asset end
    warn("[ImmortalityIncremental] Could not load " .. name .. " texture: " .. tostring(asset))
    return nil
end

local function applyTexture(targetButton, name)
    local asset = textureAsset(name)
    if not asset or not alive or not targetButton.Parent then return end
    local image = new("ImageLabel", {
        Name = "WorldTexture", BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1), Image = asset, ScaleType = Enum.ScaleType.Crop,
        ZIndex = targetButton.ZIndex, Active = false,
    }, targetButton)
    new("UICorner", {CornerRadius = UDim.new(0, 10)}, image)
    new("TextLabel", {
        Name = "Caption", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1),
        Text = targetButton.Text, TextColor3 = targetButton.TextColor3,
        Font = targetButton.Font, TextSize = targetButton.TextSize,
        TextStrokeColor3 = targetButton.TextColor3.R < 0.5 and Color3.new(1, 1, 1) or Color3.new(0, 0, 0),
        TextStrokeTransparency = 0.65, ZIndex = targetButton.ZIndex + 1, Active = false,
    }, targetButton)
    targetButton.Text = ""
end

local tileTweens = {}
local function teleportButton(name, position, x, y, width)
    local targetButton = button(name, x, y, width)
    targetButton.AutoButtonColor = false
    local border = targetButton:FindFirstChildOfClass("UIStroke")
    local normalBorder = name == "Halloween Teleport" and Color3.fromRGB(255, 223, 158)
        or Color3.fromRGB(208, 196, 231)
    border.Color = normalBorder
    border.Transparency = 0.72
    local function hover(enabled)
        if tileTweens[targetButton] then tileTweens[targetButton]:Cancel() end
        local tween = TweenService:Create(border, TweenInfo.new(0.14), {
            Color = enabled and Theme.Accent or normalBorder,
            Transparency = enabled and 0.1 or 0.72,
        })
        tileTweens[targetButton] = tween
        tween:Play()
    end
    connect(targetButton.MouseEnter, function() hover(true) end)
    connect(targetButton.MouseLeave, function() hover(false) end)
    local colors = worldColors[name]
    if colors then
        targetButton.BackgroundColor3 = colors.Background
        targetButton.TextColor3 = colors.Text
    end
    connect(targetButton.Activated, function() teleport(name, position) end)
    if textureData[name] or textureAssetIds[name] then
        task.spawn(applyTexture, targetButton, name)
    end
    return targetButton
end

