local dragging, dragStart, startPosition, dragTarget
local mascotDragMoved = false
local function beginDrag(input, target)
    if launching then return end
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        dragging, dragStart, startPosition = input, input.Position, target.Position
        dragTarget = target
        if target == mascotButton then mascotDragMoved = false end
    end
end
connect(title.InputBegan, function(input) beginDrag(input, frame) end)
connect(headerLogo.InputBegan, function(input) beginDrag(input, frame) end)
connect(titleText.InputBegan, function(input) beginDrag(input, frame) end)
connect(mascotButton.InputBegan, function(input) beginDrag(input, mascotButton) end)
connect(minimize.Activated, function() setMinimized(true) end)
connect(mascotButton.Activated, function()
    if not mascotDragMoved then setMinimized(false) end
end)
connect(UIS.InputChanged, function(input)
    local mouse = input.UserInputType == Enum.UserInputType.MouseMovement
    if dragging and (input == dragging or (mouse and dragging.UserInputType == Enum.UserInputType.MouseButton1)) then
        local delta = input.Position - dragStart
        if dragTarget == mascotButton and (math.abs(delta.X) > 4 or math.abs(delta.Y) > 4) then
            mascotDragMoved = true
        end
        dragTarget.Position = UDim2.new(startPosition.X.Scale, startPosition.X.Offset + delta.X,
            startPosition.Y.Scale, startPosition.Y.Offset + delta.Y)
    end
end)
connect(UIS.InputEnded, function(input)
    if input == dragging then
        if dragTarget == mascotButton then minimizedPosition = mascotButton.Position end
        dragging, dragTarget = nil, nil
    end
end)
connect(gui.Destroying, function()
    alive = false
    for _, tween in ipairs(startupTweens) do tween:Cancel() end
    for _, tween in ipairs(yieldTweens) do tween:Cancel() end
    for _, tween in pairs(tileTweens) do tween:Cancel() end
    stopWalking()
    for _, connection in ipairs(connections) do connection:Disconnect() end
end)

local function startupTween(object, duration, properties, style)
    local tween = TweenService:Create(object,
        TweenInfo.new(duration, style or Enum.EasingStyle.Quint, Enum.EasingDirection.Out), properties)
    table.insert(startupTweens, tween)
    tween:Play()
    return tween
end

local function awaitStartup(tween)
    local result = tween.Completed:Wait()
    return alive and result == Enum.PlaybackState.Completed
end

local function showPanel()
    if not alive then return end
    intro.Visible = false
    local destination = frame.Position
    frame.Position = UDim2.new(destination.X.Scale, destination.X.Offset,
        destination.Y.Scale, destination.Y.Offset + 14)
    frame.GroupTransparency = 1
    frame.Visible = true
    if awaitStartup(startupTween(frame, 0.35, {
        GroupTransparency = 0, Position = destination,
    })) then
        launching = false
        table.clear(startupTweens)
    end
end

task.spawn(function()
    -- Register each embedded asset once, then preload before starting the reveal.
    local logoAsset = textureAsset("Logo")
    local mascotAsset = textureAsset("Mascot")
    if not alive then return end
    if logoAsset then
        headerLogo.Image = logoAsset
        introLogo.Image = logoAsset
    end
    if mascotAsset then
        mascotButton.Image = mascotAsset
        introMascot.Image = mascotAsset
    end
    refreshBrandImages()
    if not logoAsset or not mascotAsset then
        showPanel()
        return
    end
    local preloadFinished = false
    task.spawn(function()
        pcall(function() ContentProvider:PreloadAsync({introLogo, introMascot}) end)
        preloadFinished = true
    end)
    local deadline = os.clock() + 1
    while alive and not preloadFinished and os.clock() < deadline do task.wait(0.05) end
    if not alive then return end
    -- Preloading is best-effort. Its status must not skip the launch animation
    -- for custom local asset URLs that already display correctly in the UI.
    headerLogo.Visible = true
    titleText.Visible = false
    intro.Visible = true
    if not awaitStartup(startupTween(introMascot, 0.35, {
        ImageTransparency = 0, Size = UDim2.fromOffset(128, 128),
    }, Enum.EasingStyle.Back)) then return end
    task.wait(0.15)
    if not alive then return end
    if not awaitStartup(startupTween(introMascot, 0.4, {
        Position = UDim2.new(0.5, 176, 0.5, 0), Size = UDim2.fromOffset(160, 140),
    })) then return end
    -- Crossfade into the matching character at the right edge of the full logo.
    startupTween(introMascot, 0.18, {ImageTransparency = 1})
    if not awaitStartup(startupTween(introLogo, 0.18, {ImageTransparency = 0})) then return end
    if not awaitStartup(startupTween(logoReveal, 0.7, {Size = UDim2.fromOffset(520, 188)})) then return end
    task.wait(0.4)
    if not alive then return end
    if not awaitStartup(startupTween(intro, 0.25, {
        GroupTransparency = 1, Position = UDim2.new(0.5, 0, 0.5, -18),
    })) then return end
    showPanel()
end)

task.spawn(function()
    while alive do
        local message, delay = collectorStep()
        status.Text = os.clock() < noticeUntil and noticeText or message
        statusDot.BackgroundColor3 = activeCollector and Theme.Accent or Theme.Muted
        task.wait(delay)
    end
end)
